<?php
namespace App\Http\Controllers;
use App\Models\Cheque;
use App\Services\ChequeAccessService;
use App\Services\ChequeService;
use Illuminate\Http\Request;
class ChequeStatusController extends Controller { public function pass(Request $r, Cheque $cheque, ChequeAccessService $a, ChequeService $s){$a->authorize($cheque,$r->user());abort_unless($r->user()->hasPermission('cheques.mark_passed'),403);$data=$r->validate(['cleared_date'=>'nullable|date','deposit_reference'=>'nullable|string|max:150','deposit_account_id'=>'nullable|exists:accounts,id','notes'=>'nullable|string|max:1000']);$s->pass($cheque,$data);return back()->with('success','Cheque marked as passed.');} public function returned(Request $r, Cheque $cheque, ChequeAccessService $a, ChequeService $s){$a->authorize($cheque,$r->user());abort_unless($r->user()->hasPermission('cheques.mark_returned'),403);$data=$r->validate(['return_date'=>'required|date','return_reason'=>'required|string|max:255','return_charge'=>'nullable|numeric|min:0','notes'=>'nullable|string|max:1000']);$s->returnCheque($cheque,$data);return back()->with('success','Cheque returned and amount restored to due.');} public function cancel(Request $r, Cheque $cheque, ChequeAccessService $a, ChequeService $s){$a->authorize($cheque,$r->user());abort_unless($r->user()->hasPermission('cheques.cancel'),403);$s->cancel($cheque,$r->input('notes',''));return back()->with('success','Cheque cancelled.');} public function replace(Request $r, Cheque $cheque, ChequeAccessService $a, ChequeService $s){$a->authorize($cheque,$r->user());abort_unless($r->user()->hasPermission('cheques.replace'),403);$d=$r->validate(['cheque_number'=>'required|string|max:100','cheque_date'=>'required|date','amount'=>'required|numeric|gt:0','bank_name'=>'required|string|max:150','branch_name'=>'nullable|string','account_holder'=>'nullable|string','account_number'=>'nullable|string','notes'=>'nullable|string','attachment'=>'nullable|file|max:5120']);$n=$s->replace($cheque,$d,$r->file('attachment'));return redirect()->route('cheques.show',$n)->with('success','Replacement cheque created.');} }
